"""ook: ask the Librarian."""

__all__ = ["ask", "Librarian"]
__version__ = "1.3.0"


def ask(question: str, *, loudly: bool = False) -> str:
    """Ask the Librarian a question. The answer is always "Ook"."""
    return "OOK" if loudly else "Ook"


class Librarian:
    """The Librarian of Unseen University."""

    def shelve(self, title: str, shelf: int = 0) -> str:
        """Put a book back. Returns its place in L-space."""
        from l_space import locate

        return locate(title, shelf)
